// v0.7: forty-five authored sectors. Old room indices are never reordered.
const p=(x,y,w,h=12,extra={})=>({x,y,w,h,...extra});
const floor=(x,w,y=151)=>p(x,y,w,180-y);
const e=(x,foot,type)=>({x,foot,type});
const ladder=(x,top,bottom)=>({x,y:top,w:18,h:bottom-top});
const lift=(x,y,w,axis,travel,period=5,extra={})=>p(x,y,w,8,{moving:true,axis,travel,period,...extra});
const buoy=(x,y,w,offset=0)=>p(x,y,w,9,{buoy:true,tideOffset:offset});
const leaf=(x,y,w,offset=0)=>p(x,y,w,9,{growth:{period:6.5,offset}});
const bridge=(x,y,w,group='a')=>p(x,y,w,8,{bridgeGroup:group});
const room=(stage,id,name,extra={})=>({stage,id:`${stage}-${id}`,name,width:640,height:180,spawn:{x:16,y:122},exitY:151,platforms:[],moving:[],ladders:[],hazards:[],enemies:[],pickups:[],...extra});
const gate=(stage,id,name,gateId,extra={})=>room(stage,id,name,{gate:{id:gateId,x:88,y:112,barrierX:175},platforms:[floor(0,177),floor(560,80)],unlockedPlatforms:[p(198,143,92),p(316,130,91),p(435,140,99)],hint:'Use TIME at the safe control. Restore its circuit to change the route.',...extra});
const recovery=[{x:109,y:132,type:'heart'},{x:149,y:132,type:'heart'},{x:189,y:132,type:'energy'}];
const arena=(stage,name,extra={})=>room(stage,'boss',name,{width:320,boss:true,platforms:[floor(0,320)],hint:'Read the warning. Move to a refuge, then attack.',...extra});

