// Explicit links coexist with legacy numeric next-room progression.
for(let i=0;i<EXPANSION_ROOMS.length;i++){
 const r=EXPANSION_ROOMS[i],next=EXPANSION_ROOMS[i+1];
 if(!r.boss&&!r.exits&&next?.stage===r.stage)r.exits=[{side:'right',target:next.id}];
}
